// Leads to score: new rows, skipping companies already applied to. Max 25 per run.
const applied = new Set($('Get Applied').all().map(i => String(i.json.company || '').trim().toLowerCase()).filter(Boolean));
const leads = $('Get new leads').all().map(i => i.json).filter(r => r.job_id).slice(0, 25);
return leads.filter(r => !applied.has(String(r.company || '').trim().toLowerCase())).map(r => ({ json: r }));

// New rows for companies already in the Applied tab: skip without scoring.
const applied = new Set($('Get Applied').all().map(i => String(i.json.company || '').trim().toLowerCase()).filter(Boolean));
const leads = $('Get new leads').all().map(i => i.json).filter(r => r.job_id).slice(0, 25);
return leads.filter(r => applied.has(String(r.company || '').trim().toLowerCase()))
  .map(r => ({ json: { job_id: r.job_id, status: 'skipped', notes: 'already applied to this company' } }));

// Pair each AI reply with its lead (same order) and set the status.
const leads = $('Prefilter').all().map(i => i.json);
return $input.all().map((item, i) => {
  const lead = leads[i];
  let r;
  try {
    const t = item.json.content[0].text;
    r = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  } catch (e) {
    return { json: { job_id: lead.job_id, status: 'failed', notes: 'scoring failed: ' + String(item.json.error?.message || e.message).slice(0, 200) } };
  }
  const score = Math.max(0, Math.min(100, parseInt(r.fit_score, 10) || 0));
  let status = 'skipped', notes = '';
  if (r.disqualified) { notes = 'auto-skip: ' + (r.disqualify_reason || 'hard filter'); }
  else if (score >= 85) status = 'queued';
  else if (score >= 70) status = 'needs_ben';
  else notes = 'low score';
  return { json: {
    job_id: lead.job_id, company: lead.company, title: lead.title, url: lead.url,
    fit_score: score, score_reason: String(r.score_reason || '').slice(0, 500),
    status, notes, apply_url: lead.apply_url || lead.url, platform: lead.platform || 'other'
  } };
});

// One message to Sage with every 70-84 lead from this run.
const rows = $input.all().map(i => i.json).filter(r => r.status === 'needs_ben');
if (!rows.length) return [];
const lines = rows.map(r => `row=${r.job_id} score=${r.fit_score} | ${r.company} - ${r.title} | ${String(r.score_reason).replace(/\s+/g, ' ')} | ${r.url}`);
return [{ json: { text: '[n8n:needs_ben]\n' + lines.join('\n') } }];
